Change(genesis='66602cd0dec37d58d03eec9518ca805a7ac38ea912d2b0c366a0b67b4b9f50b6', deps=(), event=Decided(decision='boxacts', at=datetime(2026, 9, 14, 0, 0, 0), actor='assistant', title="A proposal can be the box's own act (Auth, Secret), performed by the same Tap through Perform", body='*A proposal can be the box\'s own act* (2026-09-14, chain `secretaryacts`, ARCHITECTURE §10.3 "Acts"): `propose_act` stores a closed `Act` — `Auth { account }` (the device-code sign-in `suzatary auth` runs) and `Secret` (Containment) — and the SAME `Tap` performs it, through a `Perform` trait held in NO record, handing the flow `Consent::given_by_tap`. A tree-walking test pins both `Consent` constructors\' caller lists. The chat sees the act\'s turns — the URL and the user code, never the device code — and a restart closes a waiting act rather than resuming it.', rationale='Decided 2026-09-14 (chain secretaryacts, ARCHITECTURE §10.3 "Acts").', supersedes=()))